{
  "print": "The Great Wave off Kanagawa (Kanagawa oki nami ura), Katsushika Hokusai, c. 1831, public domain",
  "boats": {
    "count": 3,
    "note": "The print shows three fishing boats, each carrying nine crew members crouched low."
  },
  "mountain": {
    "name": "Mount Fuji (Fuji-san)",
    "note": "Snow-capped, small in the center-right background, dwarfed by the wave."
  },
  "palette": {
    "paper": "#e8dcc0",
    "deep_prussian_blue": "#1a3a6b",
    "medium_blue": "#2a5a8b",
    "pale_blue": "#7ba7c9",
    "foam_white": "#f2ede0",
    "boat_wood": "#c9a06a"
  },
  "composition": "Great curling wave dominates the left, breaking over the boats; Mount Fuji sits small and central in the background; a second wave rolls on the right; three boats scattered across the water.",
  "assumptions": [
    "Low poly = flat-shaded primitives (cones, torus, boxes, spheres), no textures.",
    "Gentle motion = wave swell + boat bobbing/rocking, Fuji static.",
    "Boat crew rendered as 9 small dark spheres per boat to match the print's nine figures.",
    "Single HTML file, only external deps: Google Fonts (none used) and three@0.170.0 from jsdelivr."
  ]
}

